export const NARUTO_V2_SKILLS={v2rasengan:{cooldown:7,cast:.3,duration:1},shadowassault:{cooldown:13,cast:.45,duration:.9},rasenshuriken:{cooldown:12,cast:.7,duration:1.15},crimsonrush:{cooldown:7,cast:.2,duration:1},tailcounter:{cooldown:12,cast:.1,duration:.8},baryonrasengan:{cooldown:10,cast:.6,duration:1.1}};
export const naruto_v2={name:'Naruto Uzumaki',assets:['naruto_v2','naruto_v2_baryon','naruto_v2_cast','naruto_v2_baryon_cast','naruto_v2_vfx','naruto_v2_baryon_vfx','naruto_v2_intro','naruto_v2_intro_vfx','naruto_v2_transform','naruto_v2_transform_vfx','naruto_v2_ultimate_actor','naruto_v2_ultimate_vfx','naruto_v2_dialogue'],stats:{hp:1400,speed:210,melee:75,skillPower:100,cooldown:100,blockChance:22,blinkChance:0,preferredRange:140},
 init(f){Object.assign(f,{baryon:false,v2Transformed:false,rage:0,rageLockUntil:0,rageReadyTick:null,personalUses:0,tailGuardUntil:0});for(const k of Object.keys(NARUTO_V2_SKILLS)){f[k+'Cd']=({v2rasengan:1,shadowassault:3,rasenshuriken:4,crimsonrush:1,tailcounter:2,baryonrasengan:4})[k]*f.cooldownFactor;f.skillUses[k]=0;}},
 tick(f,dt){for(const k of Object.keys(NARUTO_V2_SKILLS))f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 onAct(f,state,d){const spec=NARUTO_V2_SKILLS[state];if(!spec)return;f[state+'Cd']=spec.cooldown*f.cooldownFactor;f.skillUses[state]++;const target=d.pickTarget(f);f.v2Target=target?.uid;if(state==='v2rasengan'&&target&&d.tick>=(f.rootUntil||0)){const fromX=f.x,fromY=f.y,dx=target.x-f.x,dy=target.y-f.y,n=Math.hypot(dx,dy)||1;f.x=target.x-dx/n*65;f.y=target.y-dy/n*65;d.clampPosition(f);f.moveX=f.moveY=0;d.event('teleported',f,{x:f.x,y:f.y,fromX,fromY,skill:state});}f.rushHits=0;if(state==='tailcounter')f.tailGuardUntil=d.tick+60;},
 beforeHit(d,f,source,h,hits){if(!f.baryon||d.tick>=f.tailGuardUntil||!d.isEnemy(f,source))return false;const dx=source.x-f.x,dy=source.y-f.y;if(dx*f.face<0)return false;f.tailGuardUntil=0;if(Math.hypot(dx,dy)<150)hits.push({source:f,target:source,value:85,knockback:40});d.event('v2Counter',f,{x:f.x,y:f.y});return true;},
 onDeath(d,f){f.tailGuardUntil=0;d.clones=d.clones.filter(c=>c.ownerUid!==f.uid);},
 updateAction(d,f,o,hits,dx,dy,distance,dt){const spec=NARUTO_V2_SKILLS[f.state];if(!spec)return false;const t=d.fighters.find(t=>t.uid===f.v2Target&&t.hp>0&&d.isEnemy(f,t))||o;
  if(f.state==='crimsonrush'&&f.age<.65&&d.tick>=(f.rootUntil||0)){const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1,move=Math.min(Math.max(0,n-65),440*dt);f.x+=tx/n*move;f.y+=ty/n*move;d.clampPosition(f);}
  if(f.state==='crimsonrush'){while(f.rushHits<3&&f.age>=[.25,.48,.72][f.rushHits]){const i=f.rushHits++;if(Math.hypot(t.x-f.x,t.y-f.y)<115){hits.push({source:f,target:t,value:[45,55,95][i],knockback:i===2?35:0});d.event('v2Impact',f,{x:t.x,y:t.y,form:'baryon',skill:'crimsonrush'});}}}
  else if(f.age>=spec.cast&&!f.hit){f.hit=true;if(f.state==='shadowassault'){d.clones=d.clones.filter(c=>c.ownerUid!==f.uid);for(const side of [-1,1]){const c=d.clampPosition({id:'naruto_v2',uid:f.uid+'-v2-clone-'+ ++d.cloneSerial,ownerUid:f.uid,team:f.team,x:f.x-f.actionY*side*55,y:f.y+f.actionX*side*55,life:8,cd:.35,age:0,face:f.face,state:'run'});d.clones.push(c);d.event('v2Clone',f,{x:c.x,y:c.y});}}
   else if(f.state==='v2rasengan'){if(Math.hypot(t.x-f.x,t.y-f.y)<125){hits.push({source:f,target:t,value:175,knockback:45});d.event('v2Impact',f,{x:t.x,y:t.y,form:'kcm',skill:f.state});}}
   else if(f.state!=='tailcounter'){const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1,red=f.state==='baryonrasengan';d.shots.push({id:f.id,ownerUid:f.uid,kind:f.state,skill:f.state,form:red?'baryon':'kcm',damage:red?250:210,splash:red?75:105,splashDamage:red?65:85,radius:red?32:35,requiresOwnerAlive:true,x:f.x+tx/n*40,y:f.y+ty/n*40,vx:tx/n*(red?580:520),vy:ty/n*(red?580:520),life:red?.65:1.5,impactEvent:'v2Impact'});d.event('fire',f,{skill:f.state});}}
  if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;},
 chooseSkill(d,f,o,dx,dy,distance){const skills=f.baryon?['tailcounter','crimsonrush','baryonrasengan']:['shadowassault','v2rasengan','rasenshuriken'];for(const k of skills)if(f[k+'Cd']===0&&(k==='shadowassault'?distance<450:k==='tailcounter'?distance<170:k==='v2rasengan'?distance>65&&distance<650:k==='crimsonrush'?distance>65&&distance<330:distance>140&&distance<(f.baryon?420:650))){d.act(f,k,dx,dy);return true;}return false;}
};
export function narutoV2Pose(f,hurt=false){const state=hurt?'hurt':f.state;if(NARUTO_V2_SKILLS[state])return {key:f.baryon?'naruto_v2_baryon_cast':'naruto_v2_cast',row:0,frame:Math.min(3,Math.floor(f.age/NARUTO_V2_SKILLS[state].duration*4))};return {key:f.baryon?'naruto_v2_baryon':'naruto_v2',row:({idle:0,run:1,melee:f.combo%2?2:3,dash:4,guard:5,hurt:6,defeat:7})[state]??0,frame:['melee','dash','hurt','defeat'].includes(state)?Math.min(3,Math.floor(f.age*10)):Math.floor(f.age*8)%4};}
